int git_index_parse(git_index *index, const char *buffer, size_t buffer_size) {
    const char *buffer_end = buffer + buffer_size;
    unsigned char expected_sha1[20];

    if (buffer_size < sizeof(git_index_header) + 20) {
        return -1; // Error: buffer too small
    }

    // Calculate SHA1 checksum of the buffer
    SHA_CTX sha1_context;
    SHA1_Init(&sha1_context);
    SHA1_Update(&sha1_context, buffer, buffer_size - 20);
    SHA1_Final(expected_sha1, &sha1_context);

    // Read index header
    git_index_header *header = (git_index_header *)buffer;
    if (memcmp(header->signature, "DIRC", 4) != 0) {
        return -2; // Error: invalid signature
    }

    size_t index_version = ntohl(header->version);
    if (index_version != 2 && index_version != 3) {
        return -3; // Error: unsupported version
    }

    index->version = index_version;
    index->entry_count = ntohl(header->entry_count);
    index->entries = NULL;
    index->entry_capacity = 0;
    index->entries_size = 0;
    index->checksum = (unsigned char *)malloc(20);
    if (!index->checksum) {
        return -4; // Error: memory allocation failed
    }

    // Process each index entry
    const char *entry_start = buffer + sizeof(git_index_header);
    for (size_t i = 0; i < index->entry_count; i++) {
        const char *entry_end = entry_start;
        while (entry_end < buffer_end && *entry_end != '\0') {
            entry_end++;
        }

        if (entry_end >= buffer_end) {
            git_index_free(index);
            return -5; // Error: incomplete entry
        }

        size_t entry_length = entry_end - entry_start + 1;
        git_index_entry *entry = (git_index_entry *)realloc(index->entries, (i + 1) * sizeof(git_index_entry));
        if (!entry) {
            git_index_free(index);
            return -4; // Error: memory allocation failed
        }

        index->entries = entry;
        index->entries[i].path = (char *)malloc(entry_length);
        if (!index->entries[i].path) {
            git_index_free(index);
            return -4; // Error: memory allocation failed
        }

        memcpy(index->entries[i].path, entry_start, entry_length);
        index->entries[i].path[entry_length - 1] = '\0'; // Null-terminate the path
        index->entries[i].mode = ntohl(*((uint32_t *)(entry_end + 1)));
        memcpy(index->entries[i].oid, entry_end + 5, 20);
        index->entries[i].file_size = ntohl(*((uint32_t *)(entry_end + 25)));
        index->entries_size += entry_length + 20;

        entry_start = entry_end + 1 + 4 + 20;
    }

    // Read any extensions
    const char *extension_start = entry_start;
    while (extension_start < buffer_end - 20) {
        const char *extension_end = extension_start;
        while (extension_end < buffer_end - 20 && *extension_end != '\0') {
            extension_end++;
        }

        if (extension_end >= buffer_end - 20) {
            git_index_free(index);
            return -6; // Error: incomplete extension
        }

        size_t extension_length = extension_end - extension_start + 1;
        git_index_extension *extension = (git_index_extension *)realloc(index->extensions, (index->extension_count + 1) * sizeof(git_index_extension));
        if (!extension) {
            git_index_free(index);
            return -4; // Error: memory allocation failed
        }

        index->extensions = extension;
        index->extensions[index->extension_count].name = (char *)malloc(extension_length);
        if (!index->extensions[index->extension_count].name) {
            git_index_free(index);
            return -4; // Error: memory allocation failed
        }

        memcpy(index->extensions[index->extension_count].name, extension_start, extension_length);
        index->extensions[index->extension_count].name[extension_length - 1] = '\0'; // Null-terminate the name
        index->extensions[index->extension_count].data = (void *)malloc(ntohl(*((uint32_t *)(extension_end + 1))));
        if (!index->extensions[index->extension_count].data) {
            git_index_free(index);
            return -4; // Error: memory allocation failed
        }

        memcpy(index->extensions[index->extension_count].data, extension_end + 1 + 4, ntohl(*((uint32_t *)(extension_end + 1))));
        index->extension_count++;

        extension_start = extension_end + 1 + 4 + ntohl(*((uint32_t *)(extension_end + 1)));
    }

    // Verify the checksum
    if (memcmp(expected_sha1, buffer_end - 20, 20) != 0) {
        git_index_free(index);
        return -7; // Error: checksum mismatch
    }

    memcpy(index->checksum, buffer_end - 20, 20);

    // Sort entries if necessary
    if (index->version == 3) {
        qsort(index->entries, index->entry_count, sizeof(git_index_entry), git_index_entry_compare);
    }

    return 0;
}

